-- Domain 28: AI | views
-- Generated by tools/split_by_domain.py. Statements keep their original order tag (@seq).

-- @seq 860
CREATE VIEW public.ai_gateway_usage_monthly WITH (security_invoker='true') AS
 SELECT tenant_id,
    (date_trunc('month'::text, created_at))::date AS month,
    feature,
    model,
    count(*) AS requests,
    sum(input_tokens) AS input_tokens,
    sum(output_tokens) AS output_tokens,
    sum(cost_usd) AS cost_usd,
    count(*) FILTER (WHERE (outcome <> 'ok'::text)) AS failures
   FROM public.ai_gateway_requests
  GROUP BY tenant_id, ((date_trunc('month'::text, created_at))::date), feature, model;

